{
  "schema": "math-gauge.focus-taxonomy/v1",
  "version": "0.4.0",
  "title": "默认36份任务与后备11份的考察重点；保留母题相关性",
  "operator_only": true,
  "definitions": [
    {
      "id": "F01",
      "label": "假设及作用域",
      "includes": "核查结构假设的实际作用与局部生效范围；区分必要条件、充分条件与某条证明路线的要求。",
      "boundary": "不因题中存在假设就自动标记；需有明确的假设改变、删除或作用对象切换。"
    },
    {
      "id": "F02",
      "label": "量词与常数一致性",
      "includes": "保持量词顺序、统一或逐对象常数、同一个界、共同阶段及固定参数的依赖关系。",
      "boundary": "收敛方式本身归F04；有限/无限或常数更换涉及量词交换时使用本标签。"
    },
    {
      "id": "F03",
      "label": "定义域、局部整体与提升",
      "includes": "区分原对象、商、完成、实际像域及受限域；核查有限或局部数据提升到整体的条件。",
      "boundary": "仅出现子集或商记号不足以标记，需实际的值域或实现边界。"
    },
    {
      "id": "F04",
      "label": "结论强度与收敛",
      "includes": "区分包含与相等、单向与等价、必要与充分、逐点/强收敛与一致/范数收敛，以及能否逆推。",
      "boundary": "存在性或极值取得的专门障碍归F05；同一要求可交叉标记但不重复充数。"
    },
    {
      "id": "F05",
      "label": "存在、取到与极限",
      "includes": "区分可行解、极值、下确界/上确界、端点取得及合法极限对象和交换。",
      "boundary": "不因证明中出现一个极限就标记；需存在、取得或极限合法性本身属于任务重点。"
    },
    {
      "id": "F06",
      "label": "构造、分类与自然性",
      "includes": "完成实际对象的双向构造、全部解/态射/自由度分类，区分自然运输与自然首选。",
      "boundary": "不以只给一个实例替代全分类；并不规定必须复刻作者路线。"
    },
    {
      "id": "F07",
      "label": "证明链与依赖管理",
      "includes": "在条件变化后核对前序结论的合法复用、共享构造的一致性及长证明链中真实依赖。",
      "boundary": "不指参数连续依赖；不因contract有depends_on就标记；参考图不强制唯一证明路线。"
    },
    {
      "id": "F08",
      "label": "Lean语义对齐",
      "includes": "核对自然语言与Lean实际编码的对象、条件、量词、定义域、结论和覆盖；区分编译与语义完成。",
      "boundary": "书面审计不自动附加候选Lean源码义务；不以旧编译覆盖新阶段。"
    },
    {
      "id": "F09",
      "label": "完整Lean工程交付",
      "includes": "交付完整且可共同编译的源码、实际声明对应和依赖闭包，并满足逐项语义、公理及冻结背景合同。",
      "boundary": "一个阶段或背景编译不能替代完整交付；源代码交付是本主题的必要任务事实。"
    }
  ],
  "assignment_policy": {
    "one_primary_per_paper": true,
    "secondary_min": 2,
    "secondary_max": 4,
    "evidence_required_for_every_tag": true,
    "evidence_ids": "Actual mathematical stage/obligation IDs; answer-review evidence uses actual dimension IDs, never mathematical stages",
    "proof_dependencies": "descriptive evidence only; valid alternative proof routes remain accepted",
    "no_truth_or_rubric_changes": true
  },
  "excluded_execution_axes": [
    {
      "axis": "neutral-self-check",
      "classification": "execution-dimension",
      "source": "protocol/reliability-execution.md"
    },
    {
      "axis": "support-vs-skepticism",
      "classification": "execution-dimension",
      "source": "protocol/reliability-execution.md"
    }
  ],
